import random
import time
import functools

class TransientError(Exception):
    pass

def retry_with_backoff(max_attempts=5, base_delay=1.0, max_delay=60.0,
                       retryable=(TransientError, TimeoutError, ConnectionError)):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            attempt = 0
            while True:
                try:
                    return fn(*args, **kwargs)
                except retryable as exc:
                    attempt += 1
                    if attempt >= max_attempts:
                        raise
                    # exponential backoff with full jitter
                    backoff = min(max_delay, base_delay * (2 ** attempt))
                    sleep_for = random.uniform(0, backoff)
                    print(f"attempt {attempt} failed: {exc}; sleeping {sleep_for:.2f}s")
                    time.sleep(sleep_for)
        return wrapper
    return decorator

@retry_with_backoff(max_attempts=5, base_delay=0.5)
def call_flaky_api():
    if random.random() < 0.7:
        raise TransientError("503 Service Unavailable")
    return {"status": "ok"}

print(call_flaky_api())
